-- Resume Database Schema
-- Generated by admin.html on 2026-10-04

-- Drop existing tables if they exist
DROP TABLE IF EXISTS works;
DROP TABLE IF EXISTS education;
DROP TABLE IF EXISTS career;
DROP TABLE IF EXISTS skills;
DROP TABLE IF EXISTS languages;

-- Works (portfolio projects) table
CREATE TABLE IF NOT EXISTS works (
    id INTEGER PRIMARY KEY,
    title TEXT,
    category TEXT,
    year TEXT,
    role TEXT,
    image TEXT,
    summary TEXT,
    description TEXT,
    tech TEXT,
    live_url TEXT,
    repo_url TEXT
);

-- Education table
CREATE TABLE IF NOT EXISTS education (
    id INTEGER PRIMARY KEY,
    graduation_year TEXT,
    institution TEXT,
    degree TEXT,
    description TEXT
);

-- Career table
CREATE TABLE IF NOT EXISTS career (
    id INTEGER PRIMARY KEY,
    date_range TEXT,
    company TEXT,
    position TEXT,
    location TEXT
);

-- Skills table
CREATE TABLE IF NOT EXISTS skills (
    id INTEGER PRIMARY KEY,
    name TEXT,
    percentage INTEGER,
    description TEXT
);

-- Language skills table
CREATE TABLE IF NOT EXISTS languages (
    id INTEGER PRIMARY KEY,
    name TEXT,
    percentage INTEGER
);

-- Insert Works Data
INSERT INTO works (title, category, year, role, image, summary, description, tech, live_url, repo_url) VALUES
('FleetPulse — IoT Telemetry Platform', 'IoT', '2025', 'Lead full-stack engineer', 'image/works/fleetpulse.svg', 'A live operations dashboard streaming data from thousands of connected sensors, with alerting and analytics built in.', 'FleetPulse gives operations teams a single, real-time view of every connected device in the field. Sensor data arrives over MQTT, is stored in a time-series database and is pushed to the browser within a second.

I designed the data pipeline and the dashboard end to end: device onboarding, live charts, a geographic view of active units and a rules engine that raises alerts when readings drift outside safe ranges.

The result: faster incident response, fewer site visits and one shared source of truth for engineering and business teams.', 'React, Node.js, MQTT, TimescaleDB, Docker', '', ''),
('Sakura Lingo — Japanese Learning App', 'Mobile', '2024', 'Product designer & developer', 'image/works/sakura-lingo.svg', 'A bite-sized Japanese course with kana drills, spaced repetition and JLPT-style quizzes.', 'Drawing on five years of living in Japan and my experience teaching the language, Sakura Lingo turns the first steps of learning Japanese into a daily five-minute habit.

Learners practise hiragana and katakana with handwriting-friendly drills, review vocabulary with spaced repetition and track their readiness for each JLPT level.

I handled the full product, from user research and Figma prototypes to the Flutter app and its Firebase backend.', 'Flutter, Firebase, Figma', '', ''),
('Edge Sensor Node Firmware', 'Embedded', '2024', 'Firmware engineer', 'image/works/edge-node.svg', 'Low-power environmental sensor firmware on Zephyr RTOS with BLE provisioning and secure over-the-air updates.', 'A battery-powered sensor node designed to run for years in the field. The firmware samples temperature, humidity and air quality, then batches readings over LoRaWAN to save power.

Key work included a BLE provisioning flow for installers, a signed OTA update pipeline and careful power profiling that brought sleep current down to the microamp range.', 'C, Zephyr RTOS, nRF52840, BLE, LoRaWAN', '', ''),
('Insight — Analytics Workspace', 'Web App', '2023', 'Applications & analytics specialist', 'image/works/insight.svg', 'A self-service analytics portal that turns operational data into dashboards business teams can use without help.', 'Insight connects to existing operational databases and lets non-technical teams explore KPIs, build reports and share dashboards.

I built the data connectors, a caching layer for heavy queries and a clean, consistent UI so stakeholders can answer their own questions instead of waiting on ad-hoc reports.', 'Vue.js, Python, FastAPI, PostgreSQL, Alibaba Cloud', '', ''),
('Kumo Design System', 'UI/UX', '2023', 'UI/UX designer', 'image/works/kumo.svg', 'A calm, accessible component library and Figma kit shared across web and mobile products.', 'Kumo (雲, “cloud”) is a design system that brings consistency to a family of products. It includes design tokens for colour, type and spacing, 60+ accessible components and clear usage guidelines.

The Figma library and the coded components share the same tokens, so designers and developers always speak the same language, and new screens ship faster.', 'Figma, Design tokens, React, Storybook', '', ''),
('Helios — Solar Yield Monitor', 'IoT', '2025', 'Personal project', 'image/works/helios.svg', 'Tracks solar panel output against weather forecasts to spot underperforming panels early.', 'Helios is a side project born from my growing interest in renewable energy. An ESP32 measures the output of each panel string and compares it with the expected yield from weather forecasts.

When output drops below the forecast, for example because of dust, shading or a failing panel, Helios sends a notification with a clear explanation.', 'ESP32, MicroPython, InfluxDB, Next.js', '', '');

